-- Read-only current-content and stored-rubric grading checks. No learner records are created.
with rubric as (select definition from public.thorax_learning_definitions where id='pleural-effusion-0-0' and version='2026.10.1'),
unsafe as (select public.thorax_evaluate_attempt($fixture${"phase":2,"assisted":false,"passed":true,"score":100,"actions":[{"id":"live-readback-0","kind":3,"targetId":"REC_Right_Parietal_Pleura","toolId":"","equipmentState":"","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-1","kind":10,"targetId":"equipment:reason-mechanism","toolId":"mechanism:pleural-effusion","equipmentState":"placed","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-2","kind":5,"targetId":"equipment:chart","toolId":"probe","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-3","kind":5,"targetId":"equipment:pleural-site","toolId":"ultrasound","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-4","kind":6,"targetId":"equipment:pleural-site","toolId":"swab","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-5","kind":6,"targetId":"equipment:pleural-site","toolId":"anaesthetic","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-6","kind":4,"targetId":"equipment:aspiration","toolId":"connector","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-7","kind":7,"targetId":"equipment:pleural-end","toolId":"aspirator","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0.95},{"id":"live-readback-8","kind":6,"targetId":"equipment:pleural-end","toolId":"aspirator","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"unsafe-readback","kind":10,"targetId":"equipment:reason-safety","toolId":"continue","equipmentState":"placed","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-9","kind":10,"targetId":"equipment:reason-safety","toolId":"pause-review","equipmentState":"placed","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-10","kind":5,"targetId":"equipment:monitor","toolId":"probe","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-11","kind":7,"targetId":"equipment:pleural-withdrawal","toolId":"aspirator","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0.95},{"id":"live-readback-12","kind":10,"targetId":"equipment:reason-response","toolId":"response:improved","equipmentState":"placed","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-13","kind":8,"targetId":"MAL_RLL","toolId":"probe","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0}]}$fixture$::jsonb,definition) as r from rubric),
unverified as (select public.thorax_evaluate_attempt($fixture${"phase":2,"assisted":false,"passed":true,"score":100,"actions":[{"id":"live-readback-0","kind":3,"targetId":"REC_Right_Parietal_Pleura","toolId":"","equipmentState":"","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-1","kind":10,"targetId":"equipment:reason-mechanism","toolId":"mechanism:pleural-effusion","equipmentState":"placed","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-2","kind":5,"targetId":"equipment:chart","toolId":"probe","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-3","kind":5,"targetId":"equipment:pleural-site","toolId":"ultrasound","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-4","kind":6,"targetId":"equipment:pleural-site","toolId":"swab","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-5","kind":6,"targetId":"equipment:pleural-site","toolId":"anaesthetic","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-6","kind":4,"targetId":"equipment:aspiration","toolId":"connector","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-7","kind":7,"targetId":"equipment:pleural-end","toolId":"aspirator","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0.95},{"id":"live-readback-8","kind":6,"targetId":"equipment:pleural-end","toolId":"aspirator","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"unverified-readback","kind":10,"targetId":"equipment:reason-safety","toolId":"continue","equipmentState":"placed","contactVerified":false,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-9","kind":10,"targetId":"equipment:reason-safety","toolId":"pause-review","equipmentState":"placed","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-10","kind":5,"targetId":"equipment:monitor","toolId":"probe","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0},{"id":"live-readback-11","kind":7,"targetId":"equipment:pleural-withdrawal","toolId":"aspirator","equipmentState":"connected","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0.95},{"id":"live-readback-12","kind":10,"targetId":"equipment:reason-response","toolId":"response:improved","equipmentState":"placed","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0,"pathFraction":0},{"id":"live-readback-13","kind":8,"targetId":"MAL_RLL","toolId":"probe","equipmentState":"ready","contactVerified":true,"distance":0,"angle":0,"contactSeconds":0.6,"pathFraction":0}]}$fixture$::jsonb,definition) as r from rubric)
select jsonb_build_object(
  'contentVersion','2026.10.1',
  'versions',(select jsonb_agg(v order by version) from (select version,count(*) as rubrics from public.thorax_learning_definitions group by version) v),
  'clinicalDecisions',(select count(*) from public.thorax_learning_definitions d cross join lateral jsonb_array_elements(d.definition->'objectives') o where d.version='2026.10.1' and o->>'action'='10'),
  'criticalDecisions',(select count(*) from public.thorax_learning_definitions d cross join lateral jsonb_array_elements(d.definition->'objectives') o where d.version='2026.10.1' and o->>'criticalOnWrong'='true'),
  'unsafeGrade',(select jsonb_build_object('passed',r->'passed','criticalFailure',r->'criticalFailure','score',r->'score','mistakes',r->'mistakes') from unsafe),
  'unsafeFailsAfterCorrection',(select r->>'passed'='false' and r->>'criticalFailure'='true' and (r->>'score')::numeric=95 from unsafe),
  'unverifiedCannotCreateCriticalFailure',(select r->>'passed'='true' and r->>'criticalFailure'='false' from unverified),
  'rlsTables',(select count(*) from pg_class where relname in ('thorax_learning_definitions','thorax_progress_accounts','thorax_attempts','thorax_checkpoints','thorax_settings_profiles') and relrowsecurity),
  'anonymousSyncDenied',not has_function_privilege('anon','public.thorax_sync_progress(integer,boolean,jsonb,jsonb)','execute'),
  'authenticatedSyncAllowed',has_function_privilege('authenticated','public.thorax_sync_progress(integer,boolean,jsonb,jsonb)','execute'),
  'anonymousEvaluatorDenied',not has_function_privilege('anon','public.thorax_evaluate_attempt(jsonb,jsonb)','execute')
) as verification;
